def schema(path,title,faqs):
 org={'@type':'LocalBusiness','@id':ORIGIN+'/#business','name':'Relevant Design','legalName':'Relevant Design Studios, LLC','url':ORIGIN+'/','logo':ORIGIN+'/assets/relevant.svg','telephone':'+1-601-736-0663','email':'discover@relevantdesign.cc','address':{'@type':'PostalAddress','streetAddress':'907 Main Street','addressLocality':'Columbia','addressRegion':'MS','postalCode':'39429','addressCountry':'US'},'areaServed':[{'@type':'City','name':'Columbia, Mississippi'},{'@type':'State','name':'Mississippi'}],'hasOfferCatalog':{'@type':'OfferCatalog','name':'Design, print, signs and websites','itemListElement':[{'@type':'OfferCatalog','name':a[1],'url':ORIGIN+'/'+a[0]+'/'} for a in SERVICES]}}
 graph=[org,{'@type':'WebSite','@id':ORIGIN+'/#website','name':'Relevant Design','url':ORIGIN+'/'},{'@type':'WebPage','@id':ORIGIN+path+'#page','name':title,'url':ORIGIN+path,'isPartOf':{'@id':ORIGIN+'/#website'},'about':{'@id':ORIGIN+'/#business'}}]
 if path!='/':graph.append({'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Home','item':ORIGIN+'/'},{'@type':'ListItem','position':2,'name':title.split('|')[0].strip(),'item':ORIGIN+path}]})
 if faqs:graph.append(faq_schema(faqs))
 if path=='/rocket-sites/':
  for name,price,tag,features in PLANS:graph.append({'@type':'Service','name':name,'provider':{'@id':ORIGIN+'/#business'},'description':tag+' Plus $199 setup.','offers':{'@type':'Offer','url':ORIGIN+path+'#plans','priceCurrency':'USD','price':str(price),'priceSpecification':{'@type':'UnitPriceSpecification','priceCurrency':'USD','price':str(price),'unitText':'month'}}})
 return {'@context':'https://schema.org','@graph':graph}

FAV=urllib.parse.quote('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32"><rect width="32" height="32" rx="6" fill="#ed1c24"/><text x="8" y="24" fill="white" font-family="Arial,sans-serif" font-size="23" font-weight="bold">R</text></svg>')
def document(path,title,desc,body,faqs=[]):
 return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{E(title)}</title><meta name="description" content="{E(desc,quote=True)}"><link rel="canonical" href="{ORIGIN}{path}"><meta name="robots" content="index,follow,max-image-preview:large"><meta name="theme-color" content="#ed1c24"><meta property="og:type" content="website"><meta property="og:site_name" content="Relevant Design"><meta property="og:title" content="{E(title,quote=True)}"><meta property="og:description" content="{E(desc,quote=True)}"><meta property="og:url" content="{ORIGIN}{path}"><meta name="twitter:card" content="summary"><meta name="twitter:title" content="{E(title,quote=True)}"><meta name="twitter:description" content="{E(desc,quote=True)}"><link rel="icon" type="image/svg+xml" href="data:image/svg+xml,{FAV}"><link rel="preload" href="/assets/manrope-800.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="/styles.css"><script type="application/ld+json">{json.dumps(schema(path,title,faqs),ensure_ascii=False).replace('</','<' + chr(92) + '/')}</script><script src="/site.js" defer></script></head><body>{header(path)}<main id="main">{body}</main>{footer()}</body></html>'''

def build():
 for path,(title,desc,render,faqs) in PAGES.items():
  dest=OUT/path.strip('/')/'index.html';dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(document(path,title,desc,render(),faqs))
 aliases={'/design-creative':'/relevant-design/','/signage-displays':'/rd-graphics/','/marketing-web':'/rocket-sites/','/contact-us':'/contact/'}
 legacy_html={'/design.html':'/relevant-design/','/signage.html':'/rd-graphics/','/marketing.html':'/rocket-sites/','/events.html':'/events-promotion/','/contact-us.html':'/contact/','/privacy.html':'/privacy/','/terms.html':'/terms/'}
 (OUT/'_redirects').write_text('\n'.join(f'{old} {new} 301\n{old}/ {new} 301' for old,new in aliases.items())+'\n'+'\n'.join(f'{old} {new} 301' for old,new in legacy_html.items())+'\n')
 for old,new in aliases.items():
  dest=OUT/old.strip('/')/'index.html';dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta http-equiv="refresh" content="0;url={new}"><link rel="canonical" href="{ORIGIN}{new}"><title>Relevant Design</title></head><body><p>This page has moved. <a href="{new}">Continue to Relevant Design</a>.</p></body></html>')
 (OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{ORIGIN}{p}</loc></url>' for p in PAGES)+'</urlset>')
 (OUT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+ORIGIN+'/sitemap.xml\n')
 (OUT/'404.html').write_text(document('/404/','Page not found | Relevant Design','Find your way back to Relevant Design.',hero('A wrong turn.<br><span class="accent">Still plenty of possibilities.</span>','Page not found','Let’s get you back to the right place.',None)+'<div class="container" style="padding-bottom:90px">'+button('Back to the homepage','/')+'</div>').replace('index,follow,max-image-preview:large','noindex,follow'))
 (OUT/'llms.txt').write_text('# Relevant Design\n\nDesign, signs, printing and websites in Columbia, Mississippi.\n\nContact: 907 Main Street, Columbia, MS 39429. Phone: +1 601-736-0663. Email: discover@relevantdesign.cc.\n\n'+''.join(f'- [{t.split("|")[0].strip()}]({ORIGIN}{p}): {d}\n' for p,(t,d,_,__) in PAGES.items()))
 (OUT/'_headers').write_text('/assets/*\n  Cache-Control: public, max-age=86400\n/*\n  X-Content-Type-Options: nosniff\n  Referrer-Policy: strict-origin-when-cross-origin\n  Permissions-Policy: camera=(), microphone=(), geolocation=()\n')
 print(f'Built {len(PAGES)} content pages, 4 legacy routes, 404, sitemap, robots and metadata for {ORIGIN}')
if __name__=='__main__':build()
